import (
	"math/rand"
	"strings"
	"testing"
)

// brutePrefix tries every border length at every position, which is the
// quadratic-or-worse approach the large tests are sized to rule out.
func brutePrefix(s string) []int {
	pi := make([]int, len(s))
	for i := range s {
		for l := i; l >= 1; l-- {
			if s[:l] == s[i+1-l:i+1] {
				pi[i] = l
				break
			}
		}
	}
	return pi
}

func equal(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestPrefixFunctionKnownCases(t *testing.T) {
	cases := []struct {
		s    string
		want []int
	}{
		{"", []int{}},
		{"a", []int{0}},
		{"aabaaab", []int{0, 1, 0, 1, 2, 2, 3}},
		{"abcabcd", []int{0, 0, 0, 1, 2, 3, 0}},
		{"aaaa", []int{0, 1, 2, 3}},
		{"abababca", []int{0, 0, 1, 2, 3, 4, 0, 1}},
	}
	for _, c := range cases {
		got := prefixFunction(c.s)
		if len(got) != len(c.want) || (len(got) > 0 && !equal(got, c.want)) {
			t.Fatalf("prefixFunction(%q) = %v, want %v", c.s, got, c.want)
		}
	}
}

func TestPrefixFunctionMatchesBruteForce(t *testing.T) {
