// TestPrefixFunctionFindsPlantedPattern is the search application and the
// timing test in one: pattern, separator, then a 250000-byte two-letter text
// with the pattern planted at known ends. Restarting the border search from
// scratch at each position is O(n^2) here and does not finish.
func TestPrefixFunctionFindsPlantedPattern(t *testing.T) {
	const patLen = 300
	const textLen = 250000
	rng := rand.New(rand.NewSource(2024))
	pattern := make([]byte, patLen)
	for i := range pattern {
		pattern[i] = "ab"[rng.Intn(2)]
	}
	text := make([]byte, textLen)
	for i := range text {
		text[i] = "ab"[rng.Intn(2)]
	}
	plants := []int{0, 999, 40000, 40500, 123456, textLen - patLen}
	for _, at := range plants {
		copy(text[at:], pattern)
	}
	s := string(pattern) + "$" + string(text)
	offset := patLen + 1

	pi := prefixFunction(s)
	if len(pi) != len(s) {
		t.Fatalf("got %d values, want %d", len(pi), len(s))
	}
	// Every reported value must be a real border. The separator appears once,
	// so no value can exceed patLen and this stays cheap.
	for i, v := range pi {
		if v < 0 || v > i {
			t.Fatalf("pi[%d] = %d is not a proper border length", i, v)
		}
		if s[:v] != s[i+1-v:i+1] {
			t.Fatalf("pi[%d] = %d but the prefix and suffix differ", i, v)
		}
	}
	hits := map[int]bool{}
	for i, v := range pi {
		if v == patLen {
			hits[i-offset] = true
		}
	}
	for _, at := range plants {
		if !hits[at+patLen-1] {
			t.Fatalf("pattern planted at %d was not reported (pi at that end is %d)", at, pi[offset+at+patLen-1])
		}
	}
	if len(hits) != len(plants) {
		t.Fatalf("reported %d full-length matches, want %d", len(hits), len(plants))
	}
}

