// primDense is the O(n^2) reference: correct, and fine on the small random
// graphs, which is exactly why the large test uses 200000 vertices.
func primDense(n int, edges [][]int) int {
	const inf = 1 << 30
	best := make([][]int, n)
	for i := range best {
		best[i] = make([]int, n)
		for j := range best[i] {
			best[i][j] = inf
		}
	}
	for _, e := range edges {
		if e[2] < best[e[0]][e[1]] {
			best[e[0]][e[1]] = e[2]
			best[e[1]][e[0]] = e[2]
		}
	}
	dist := make([]int, n)
	done := make([]bool, n)
	for i := range dist {
		dist[i] = inf
	}
	dist[0] = 0
	total := 0
	for it := 0; it < n; it++ {
		u := -1
		for v := 0; v < n; v++ {
			if !done[v] && (u == -1 || dist[v] < dist[u]) {
				u = v
			}
		}
		if dist[u] == inf {
			return -1
		}
		done[u] = true
		total += dist[u]
		for v := 0; v < n; v++ {
			if !done[v] && best[u][v] < dist[v] {
				dist[v] = best[u][v]
			}
		}
	}
	return total
}

