// spanning every vertex, buried under expensive edges. Scanning all vertices to
// pick the next one is 9*10^10 steps here.
func TestMSTOnLargeSparseGraph(t *testing.T) {
	const n = 300000
	rng := rand.New(rand.NewSource(9))
	edges := make([][]int, 0, 1000000)
	for i := 0; i+1 < n; i++ {
		edges = append(edges, []int{i, i + 1, 1})
	}
	for i := 0; i < 700000; i++ {
		u, v := rng.Intn(n), rng.Intn(n)
		if u == v {
			continue
		}
		edges = append(edges, []int{u, v, 1000 + rng.Intn(1000)})
	}
	rng.Shuffle(len(edges), func(i, j int) { edges[i], edges[j] = edges[j], edges[i] })
	if got := minimumSpanningTree(n, edges); got != n-1 {
		t.Fatalf("got %d, want %d", got, n-1)
	}
