import "sort"

// minimumSpanningTree runs Kruskal: cheapest edge first, kept only when it
// joins two different components, tracked by a union-find.
func minimumSpanningTree(n int, edges [][]int) int {
	if n <= 1 {
		return 0
	}
	order := make([]int, len(edges))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		return edges[order[a]][2] < edges[order[b]][2]
	})
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i] = i
		size[i] = 1
	}
	var find func(int) int
	find = func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	total, joined := 0, 0
	for _, i := range order {
		e := edges[i]
		a, b := find(e[0]), find(e[1])
		if a == b {
			continue
		}
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
		total += e[2]
		joined++
		if joined == n-1 {
			return total
		}
	}
	return -1
}

