import (
	"math/rand"
	"testing"
)

// walkDP is the step-at-a-time reference: O(k*n^2), fine for small k and the
// reason the big cases use k near 10^18.
func walkDP(adj [][]int, k, mod int) int {
	n := len(adj)
	cur := make([]int, n)
	cur[0] = 1 % mod
	for step := 0; step < k; step++ {
		next := make([]int, n)
		for u := 0; u < n; u++ {
			if cur[u] == 0 {
				continue
			}
			for v := 0; v < n; v++ {
				next[v] = (next[v] + cur[u]*adj[u][v]) % mod
			}
		}
		cur = next
	}
	return cur[n-1]
}

