// TestCountWalksOnHugeK walks a directed cycle of 101 vertices, so a walk of
// length k from vertex 0 ends at k mod 101 and the answer needs no reference
// implementation. 10^18 = -1 mod 101, which is the last vertex. Taking one step
// at a time is 10^18 iterations.
func TestCountWalksOnHugeK(t *testing.T) {
	const n = 101
	adj := make([][]int, n)
	for i := range adj {
		adj[i] = make([]int, n)
		adj[i][(i+1)%n] = 1
	}
	if got := countWalks(adj, 1000000000000000000, mod); got != 1 {
		t.Fatalf("k=10^18: got %d, want 1", got)
	}
	if got := countWalks(adj, 1000000000000000001, mod); got != 0 {
		t.Fatalf("k=10^18+1: got %d, want 0", got)
	}
}

