// countWalks raises the adjacency matrix to the k-th power by repeated
// squaring and reads off entry [0][n-1].
func countWalks(adj [][]int, k int, mod int) int {
	n := len(adj)
	mul := func(a, b [][]int) [][]int {
		out := make([][]int, n)
		for i := range out {
			out[i] = make([]int, n)
		}
		for i := 0; i < n; i++ {
			for t := 0; t < n; t++ {
				if a[i][t] == 0 {
					continue
				}
				av := a[i][t]
				for j := 0; j < n; j++ {
					out[i][j] = (out[i][j] + av*b[t][j]) % mod
				}
			}
		}
		return out
	}
	result := make([][]int, n)
	base := make([][]int, n)
	for i := 0; i < n; i++ {
		result[i] = make([]int, n)
		result[i][i] = 1 % mod
		base[i] = make([]int, n)
		for j := 0; j < n; j++ {
			base[i][j] = adj[i][j] % mod
		}
	}
	for k > 0 {
		if k&1 == 1 {
			result = mul(result, base)
		}
		base = mul(base, base)
		k >>= 1
	}
	return result[0][n-1]
}
